package share

import (
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"time"
)

// LinkTTL is how long a share link stays valid.
const LinkTTL = 7 * 24 * time.Hour

// Register mounts the share endpoints.
func Register(r Router) {
	r.POST("/schedules/:id/share", Create)
	r.GET("/share/:token", Get)
}

// Link is the JSON form of contract.ShareLink (packages/contract/src/share.ts).
type Link struct {
	Token      string `json:"token"`
	ScheduleID string `json:"scheduleId"`
	ExpiresAt  string `json:"expiresAt"`
}

// Create makes an opaque token for a schedule the caller owns.
func Create(c Ctx) error {
	s, err := c.Schedules().Get(c.Param("id"))
	if err != nil {
		return c.NoContent(http.StatusNotFound)
	}
	if s.OwnerID != c.UserID() {
		return c.NoContent(http.StatusForbidden)
	}
	tok, err := newToken()
	if err != nil {
		return c.NoContent(http.StatusInternalServerError)
	}
	exp := c.Now().Add(LinkTTL)
	if err := c.Links().Save(tok, s.ID, exp); err != nil {
		return c.NoContent(http.StatusInternalServerError)
	}
	return c.JSON(http.StatusCreated, Link{Token: tok, ScheduleID: s.ID, ExpiresAt: exp.UTC().Format(time.RFC3339)})
}

// Get returns the schedule read-only; unknown or expired tokens are 404.
func Get(c Ctx) error {
	l, ok := c.Links().Find(c.Param("token"))
	if !ok || !c.Now().Before(l.ExpiresAt) {
		return c.NoContent(http.StatusNotFound)
	}
	return c.JSON(http.StatusOK, c.Schedules().ReadOnly(l.ScheduleID))
}

// newToken returns 16 random bytes from crypto/rand, hex-encoded: opaque, not a JWT (ADR 0007).
func newToken() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

