package share

import (
	"errors"
	"net/http"
	"testing"
	"time"
)

var now = time.Date(2026, 11, 16, 9, 0, 0, 0, time.UTC)

type fakeSchedules map[string]Schedule

func (f fakeSchedules) Get(id string) (Schedule, error) {
	if s, ok := f[id]; ok {
		return s, nil
	}
	return Schedule{}, errors.New("not found")
}
func (f fakeSchedules) ReadOnly(id string) any { return map[string]string{"id": id, "mode": "read-only"} }

type fakeLinks map[string]StoredLink

func (f fakeLinks) Save(tok, id string, exp time.Time) error { f[tok] = StoredLink{id, exp}; return nil }
func (f fakeLinks) Find(tok string) (StoredLink, bool)      { l, ok := f[tok]; return l, ok }

type fakeCtx struct {
	params map[string]string
	user   string
	links  fakeLinks
	status int
	body   any
}

func (c *fakeCtx) Param(n string) string        { return c.params[n] }
func (c *fakeCtx) UserID() string               { return c.user }
func (c *fakeCtx) Now() time.Time               { return now }
func (c *fakeCtx) Schedules() Schedules         { return fakeSchedules{"s1": {ID: "s1", OwnerID: "owner"}} }
func (c *fakeCtx) Links() Links                 { return c.links }
func (c *fakeCtx) JSON(code int, v any) error   { c.status, c.body = code, v; return nil }
func (c *fakeCtx) NoContent(code int) error     { c.status = code; return nil }

func call(h func(Ctx) error, user string, params map[string]string, links fakeLinks) *fakeCtx {
	c := &fakeCtx{params: params, user: user, links: links}
	if err := h(c); err != nil {
		panic(err)
	}
	return c
}

func TestCreateReturnsLinkMatchingContract(t *testing.T) {
	links := fakeLinks{}
	c := call(Create, "owner", map[string]string{"id": "s1"}, links)
	l, _ := c.body.(Link)
	if c.status != http.StatusCreated || len(l.Token) != 32 || l.ScheduleID != "s1" ||
		l.ExpiresAt != now.Add(LinkTTL).Format(time.RFC3339) {
		t.Fatalf("got %d %+v", c.status, c.body)
	}
	if _, ok := links[l.Token]; !ok {
		t.Fatal("link not saved")
	}
}

func TestCreateRejectsNonOwner(t *testing.T) {
	links := fakeLinks{}
	if c := call(Create, "stranger", map[string]string{"id": "s1"}, links); c.status != http.StatusForbidden || len(links) != 0 {
		t.Fatalf("got %d, %d links", c.status, len(links))
	}
}

func TestCreateUnknownScheduleIs404(t *testing.T) {
	if c := call(Create, "owner", map[string]string{"id": "nope"}, fakeLinks{}); c.status != http.StatusNotFound {
		t.Fatalf("got %d", c.status)
	}
}

func TestGetReturnsReadOnlySchedule(t *testing.T) {
	links := fakeLinks{"t1": {ScheduleID: "s1", ExpiresAt: now.Add(time.Hour)}}
	c := call(Get, "", map[string]string{"token": "t1"}, links)
	if body, _ := c.body.(map[string]string); c.status != http.StatusOK || body["mode"] != "read-only" {
		t.Fatalf("got %d %+v", c.status, c.body)
	}
}

func TestGetUnknownTokenIs404(t *testing.T) {
	if c := call(Get, "", map[string]string{"token": "nope"}, fakeLinks{}); c.status != http.StatusNotFound {
		t.Fatalf("got %d", c.status)
	}
}

func TestGetExpiredTokenIs404(t *testing.T) {
	links := fakeLinks{"t1": {ScheduleID: "s1", ExpiresAt: now}}
	if c := call(Get, "", map[string]string{"token": "t1"}, links); c.status != http.StatusNotFound {
		t.Fatalf("got %d", c.status)
	}
}

