import { useState } from 'react'
import type { ShareLink } from '@app/contract'

/** Copies a schedule's public share link, and says so when the copy fails. */
export function ShareButton({ link }: { link: ShareLink }) {
  const [error, setError] = useState<string | null>(null)
  const url = `${location.origin}/share/${link.token}`

  async function copy() {
    setError(null)
    try {
      await navigator.clipboard.writeText(url)
    } catch {
      setError(`Couldn't copy the link. Copy it manually: ${url}`)
    }
  }

  return (
    <>
      <button onClick={copy}>Copy link (valid until {link.expiresAt})</button>
      {error && <p role="alert">{error}</p>}
    </>
  )
}

