import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { expect, test, vi } from 'vitest'
import { ShareButton } from './Button'

const link = { token: 't1', scheduleId: 's1', expiresAt: '2026-12-01T00:00:00Z' }

test('copies the share link', async () => {
  const writeText = vi.fn().mockResolvedValue(undefined)
  Object.assign(navigator, { clipboard: { writeText } })
  render(<ShareButton link={link} />)
  await userEvent.click(screen.getByRole('button'))
  expect(writeText).toHaveBeenCalledWith(expect.stringContaining('/share/t1'))
  expect(screen.queryByRole('alert')).toBeNull()
})

test('shows an error when copying fails', async () => {
  Object.assign(navigator, { clipboard: { writeText: vi.fn().mockRejectedValue(new Error('denied')) } })
  render(<ShareButton link={link} />)
  await userEvent.click(screen.getByRole('button'))
  expect(await screen.findByRole('alert')).toHaveTextContent("Couldn't copy the link")
})

