package share

import "time"

// Router is the subset of the HTTP router this package uses.
type Router interface {
	POST(path string, h func(Ctx) error)
	GET(path string, h func(Ctx) error)
}

// Ctx is what a handler receives for one request.
type Ctx interface {
	Param(name string) string
	UserID() string
	Now() time.Time
	Schedules() Schedules
	Links() Links
	JSON(code int, v any) error
	NoContent(code int) error
}

// Schedule is the part of a schedule the share handlers need.
type Schedule struct{ ID, OwnerID string }

// Schedules reads schedules.
type Schedules interface {
	Get(id string) (Schedule, error)
	ReadOnly(id string) any
}

// StoredLink is a saved share link.
type StoredLink struct {
	ScheduleID string
	ExpiresAt  time.Time
}

// Links stores share links by token.
type Links interface {
	Save(token, scheduleID string, expiresAt time.Time) error
	Find(token string) (StoredLink, bool)
}
